// 1. Local Automatic Variables (Built-in Types)
// Result: Default initialized to an indeterminate value.

void automatic_init() {
    int x;       // Indeterminate value
    double arr[2]; // Both elements indeterminate

    struct LocalPOD { int a; char b; };
    LocalPOD lp; // a and b are indeterminate
}

// 2. Static/Global Duration Variables
// Result: Default initialized to zero (Zero Initialization).

static int static_i;   // Initialized to 0
double global_d;       // Initialized to 0.0

struct GlobalArray {
    int data[3];
};
GlobalArray ga;       // All elements initialized to 0

// 3. Class Types (Invoking Default Constructor)
// Result: Type determines initialization via constructor rules.

struct CustomType {
    int member;
    CustomType() : member(42) {} // User-defined ctor
};

void class_init() {
    CustomType obj1;  // Calls CustomType::CustomType()

    // Placement new (still default initialization)
    CustomType* ptr = new CustomType; 
}
